import math
    import random
    import time

    LANGUAGE_WRAPPER = 'On a circular table with {n_seats} seats arranged in a cycle, the integers 1, 2, ..., {n_seats} are placed one per seat. Two seats are considered adjacent if they are next to each other on the circle. Let S be a real number such that, for every pair of adjacent seats, the sum of the two integers written on them is at least S. Determine, in terms of {n_seats}, the maximum possible value of S under an optimal arrangement.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose a non-trivial cycle size; avoid tiny trivial cases for better training value.
# We allow both even and odd, to enforce the piecewise reasoning.
# Retry to ensure not too small.
for _ in range(100):
    n = rng.randint(6, 99)  # moderate size; both parities appear.
    if n >= 6:
        return {"n_seats": n}
# fallback
return {"n_seats": 8}

    def verifier(assign):
# Validate input
if not isinstance(assign, dict):
    # invalid assignment structure
    return (False, None)
if 'n_seats' not in assign:
    # required slot missing
    return (False, None)
n = assign['n_seats']
if not isinstance(n, int):
    # type check fail
    return (False, None)
if n < 3:
    # Cycle must have at least 3 seats
    return (False, None)
# Compute the answer: For a cycle C_n, the optimal arrangement maximizes
# the minimum adjacent sum. The exact value is piecewise:
# - If n is even: max S = n + 1.
#   Construction: Alternating extremes: n, 1, n-1, 2, ..., around the cycle.
#   Every adjacent pair sums to n+1. Tightness: Any labeling forces a pair with sum <= n+1.
# - If n is odd: max S = n.
#   Construction: Modified alternating extremes produces minimum adjacent sum n.
#   Tightness: 1 has two neighbors; by pigeonhole/averaging, at least one neighbor <= n-1,
#   forcing min sum <= n.
if n % 2 == 0:
    answer = n + 1
else:
    answer = n
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

